# 泰山杯 2021 — crypto C组密码题（原题脚本，来自公开 writeup 重建）
# 原题把 flag 分两段 flag1/flag2，分别用不同 RSA 结构加密。
# 第一段：n1=p1*q1(1024bit)，给 hint=pow(1024*p1-197*q1, n1-p1-q1, n1)，
#         开方后两式相加可恢复 2048*p1，从而得 p1,q1 解 RSA 得 flag1。
# 第二段：n2=p2*q2(512bit)，给 c2=pow(flag2,p2,n2), c3=pow(flag2,q2,n2)，
#         用小素数/已知 p2,q2 比特结构恢复 flag2。
import gmpy2
from Crypto.Util.number import *

# ---- 原题加密逻辑（实例参数见下方，来自公开 writeup） ----
def build_challenge(flag1, flag2):
    p1 = getPrime(1024); q1 = getPrime(1024)
    p2 = getPrime(512);  q2 = getPrime(512)
    n1 = p1 * q1
    n2 = p2 * q2
    e  = 65537
    hint = pow(1024*p1 - 197*q1, n1 - p1 - q1, n1)
    c1 = pow(flag1, e, n1)
    c2 = pow(flag2, p2, n2)
    c3 = pow(flag2, q2, n2)
    return dict(n1=n1, c1=c1, hint=hint, n2=n2, c2=c2, c3=c3)

